namespace HomeUtilities.ViewModels;

/// <summary>A section of the user guide that a screen's "?" button opens.</summary>
public enum HelpTopic
{
    Overview,
    Properties,
    Suppliers,
    Contracts,
    Meters,
    Readings,
    Categories,
    Tariffs,
    VatRates,
    Charges,
    Bills,
    BillFromPdf,
    BillTemplates,
    Payments,
    EqualizedPayments,
    PropertyTax,
    Reports,
    Settings,
    LanguageAndTheme,
    Reminders,
    Backup,
    Sync,
    ErrorLog,
    Imports,
    About,
}

/// <summary>Maps a <see cref="HelpTopic"/> to the heading anchor (generated by Markdig) in each guide language.</summary>
public static class HelpTopics
{
    // Anchors follow the numbered headings of docs/user-guide/*.md; HelpContentServiceTests checks that they exist.
    private static readonly Dictionary<HelpTopic, (string En, string Ru)> Anchors = new()
    {
        [HelpTopic.Overview] = ("4-overview", "4-обзор"),
        [HelpTopic.Properties] = ("5-properties", "5-объекты"),
        [HelpTopic.Suppliers] = ("6-suppliers", "6-поставщики"),
        [HelpTopic.Contracts] = ("7-contracts", "7-договоры"),
        [HelpTopic.Meters] = ("8-meters", "8-счётчики"),
        [HelpTopic.Readings] = ("9-readings", "9-показания"),
        [HelpTopic.Categories] = ("10-categories", "10-категории"),
        [HelpTopic.Tariffs] = ("11-tariffs", "11-тарифы"),
        [HelpTopic.VatRates] = ("vat-rates", "ставки-ндс"),
        [HelpTopic.Charges] = ("12-charges", "12-начисления"),
        [HelpTopic.Bills] = ("13-bills", "13-счета"),
        [HelpTopic.BillFromPdf] = ("filling-a-bill-from-a-pdf", "заполнение-счёта-из-pdf"),
        [HelpTopic.BillTemplates] = ("14-bill-templates-and-drafts", "14-шаблоны-счетов-и-черновики"),
        [HelpTopic.Payments] = ("15-payments", "15-платежи"),
        [HelpTopic.EqualizedPayments] = ("16-equalized-payments", "16-равномерные-платежи"),
        [HelpTopic.PropertyTax] = ("17-property-tax", "17-налог-на-недвижимость"),
        [HelpTopic.Reports] = ("18-reports", "18-отчёты"),
        [HelpTopic.Settings] = ("19-settings", "19-настройки"),
        [HelpTopic.LanguageAndTheme] = ("language-and-theme", "язык-и-тема"),
        [HelpTopic.Reminders] = ("reminders", "напоминания"),
        [HelpTopic.Backup] = ("backup", "резервная-копия"),
        [HelpTopic.Sync] = ("sync", "синхронизация"),
        [HelpTopic.ErrorLog] = ("error-log", "журнал-ошибок"),
        [HelpTopic.Imports] = ("imports-and-profiles", "импорты-и-профили"),
        [HelpTopic.About] = ("about", "о-приложении"),
    };

    public static string GetAnchor(HelpTopic topic, string language) =>
        language == HelpContentService.RussianLanguage ? Anchors[topic].Ru : Anchors[topic].En;
}
